#[summary("first occurrence of x in sorted array via binary search")]
mod tasks {
    spec fn bounds(a: &[i64], lo: usize, hi: usize) -> bool {
        lo <= hi && hi <= a.len()
    }

    #[effects(pure)]
    #[uses(bounds, first_result, lower_ok, sorted, upper_ok)]
    fn first_in_sorted(arr: &[i64], x: i64) -> (r: i64)
        requires sorted(arr),
        ensures first_result(arr, x, r),
    {
        let mut lo: usize = 0;
        let mut hi: usize = arr.len();
        while lo < hi
            invariant bounds(arr, lo, hi), lower_ok(arr, x, lo), upper_ok(arr, x, hi), sorted(arr),
            decreases hi - lo,
        {
            let mid: usize = lo + (hi - lo) / 2;
            if arr[mid] < x {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if lo < arr.len() && arr[lo] == x {
            lo as i64
        } else {
            -1
        }
    }

    spec fn first_result(a: &[i64], x: i64, r: i64) -> bool {
        if r >= 0 {
            r < a.len() && (forall|k: usize| k == r ==> #[trigger] a[k] == x) && (forall|k: usize| k < r ==> #[trigger] a[k] != x)
        } else {
            r == -1 && (forall|k: usize| k < a.len() ==> #[trigger] a[k] != x)
        }
    }

    spec fn lower_ok(a: &[i64], x: i64, lo: usize) -> bool {
        lo <= a.len() && (forall|k: usize| k < lo ==> #[trigger] a[k] < x)
    }

    spec fn sorted(a: &[i64]) -> bool {
        forall|i: usize, j: usize| i <= j && j < a.len() ==> #[trigger] a[i] <= #[trigger] a[j]
    }

    spec fn upper_ok(a: &[i64], x: i64, hi: usize) -> bool {
        hi <= a.len() && (forall|k: usize| hi <= k && k < a.len() ==> x <= #[trigger] a[k])
    }
}

#[summary("k-th smallest element via successive distinct-value counting")]
mod tasks {
    spec fn all_ge(a: &[i64], x: i64, n: usize) -> bool {
        forall|i: usize| i < n && i < a.len() ==> #[trigger] a[i] >= x
    }

    spec fn all_le(a: &[i64], x: i64, n: usize) -> bool {
        forall|i: usize| i < n && i < a.len() ==> #[trigger] a[i] <= x
    }

    spec fn cnt_bound(c: usize, j: usize) -> bool {
        c <= j
    }

    spec fn cnt_le_eq(a: &[i64], x: i64, n: usize, c: usize) -> bool {
        count_le(a, x, n) == c
    }

    spec fn cnt_lt_eq(a: &[i64], x: i64, n: usize, c: usize) -> bool {
        count_lt(a, x, n) == c
    }

    spec fn count_le(a: &[i64], x: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            count_le(a, x, n - 1) + (if a[n - 1] <= x { 1 } else { 0 })
        }
    }

    #[effects(pure)]
    #[uses(cnt_bound, cnt_le_eq, count_le, idx_ok)]
    fn count_le_fn(a: &[i64], x: i64) -> (c: usize)
        ensures cnt_le_eq(a, x, a.len(), c),
    {
        let n: usize = a.len();
        let mut j: usize = 0;
        let mut cnt: usize = 0;
        while j < n
            invariant idx_ok(j, n), cnt_le_eq(a, x, j, cnt), cnt_bound(cnt, j),
            decreases n - j,
        {
            cnt = if a[j] <= x {
                cnt + 1
            } else {
                cnt
            };
            j = j + 1;
        }
        cnt
    }

    spec fn count_lt(a: &[i64], x: i64, n: usize) -> usize
        decreases n,
    {
        if n == 0 || n > a.len() {
            0
        } else {
            count_lt(a, x, n - 1) + (if a[n - 1] < x { 1 } else { 0 })
        }
    }

    spec fn dominated(a: &[i64], cur: i64, nxt: i64, n: usize) -> bool {
        forall|i: usize| i < n && i < a.len() ==> #[trigger] a[i] <= cur || a[i] >= nxt
    }

    spec fn gt(x: i64, y: i64) -> bool {
        x > y
    }

    spec fn idx_ok(j: usize, n: usize) -> bool {
        j <= n
    }

    spec fn k_in(a: &[i64], k: usize) -> bool {
        k < a.len()
    }

    spec fn kth_ok(a: &[i64], r: i64, k: usize) -> bool {
        count_lt(a, r, a.len()) <= k && k < count_le(a, r, a.len())
    }

    #[effects(pure)]
    #[uses(all_ge, all_le, cnt_le_eq, cnt_lt_eq, k_in, kth_ok, le_k, lt_eq_le, within)]
    fn kth_smallest(arr: &[i64], k: usize) -> (r: i64)
        requires k_in(arr, k),
        ensures kth_ok(arr, r, k),
    {
        let n: usize = arr.len();
        let mut cur: i64 = -9223372036854775807 - 1;
        lemma_lt_zero(arr, cur, n);
        let mut lt: usize = 0;
        let mut c: usize = count_le_fn(arr, cur);
        while c <= k
            invariant k_in(arr, k), cnt_lt_eq(arr, cur, n, lt), le_k(lt, k), cnt_le_eq(arr, cur, n, c),
            decreases 9223372036854775807 - cur,
        {
            if cur == 9223372036854775807 {
                lemma_le_all(arr, cur, n);
            } else {
                let nxt: i64 = next_greater(arr, cur);
                lemma_eq(arr, cur, nxt, n);
                lt = c;
                cur = nxt;
                c = count_le_fn(arr, cur);
            }
        }
        cur
    }

    spec fn le_k(l: usize, k: usize) -> bool {
        l <= k
    }

    #[effects(pure)]
    #[uses(count_le, count_lt, dominated, gt, lt_eq_le, within)]
    fn lemma_eq(a: &[i64], cur: i64, nxt: i64, n: usize) -> ()
        requires within(a, n), gt(nxt, cur), dominated(a, cur, nxt, n),
        ensures lt_eq_le(a, cur, nxt, n),
        decreases n,
    {
        if n == 0 {} else {
            lemma_eq(a, cur, nxt, n - 1);
        }
    }

    #[effects(pure)]
    #[uses(all_le, cnt_le_eq, count_le, within)]
    fn lemma_le_all(a: &[i64], x: i64, n: usize) -> ()
        requires within(a, n), all_le(a, x, n),
        ensures cnt_le_eq(a, x, n, n),
        decreases n,
    {
        if n == 0 {} else {
            lemma_le_all(a, x, n - 1);
        }
    }

    #[effects(pure)]
    #[uses(all_ge, cnt_lt_eq, count_lt, within)]
    fn lemma_lt_zero(a: &[i64], x: i64, n: usize) -> ()
        requires within(a, n), all_ge(a, x, n),
        ensures cnt_lt_eq(a, x, n, 0),
        decreases n,
    {
        if n == 0 {} else {
            lemma_lt_zero(a, x, n - 1);
        }
    }

    spec fn lt_eq_le(a: &[i64], cur: i64, nxt: i64, n: usize) -> bool {
        count_lt(a, nxt, n) == count_le(a, cur, n)
    }

    spec fn lt_max(x: i64) -> bool {
        x < 9223372036854775807
    }

    #[effects(pure)]
    #[uses(dominated, gt, idx_ok, lt_max)]
    fn next_greater(a: &[i64], cur: i64) -> (r: i64)
        requires lt_max(cur),
        ensures gt(r, cur), dominated(a, cur, r, a.len()),
    {
        let n: usize = a.len();
        let mut nxt: i64 = 9223372036854775807;
        let mut i: usize = 0;
        while i < n
            invariant idx_ok(i, n), gt(nxt, cur), dominated(a, cur, nxt, i),
            decreases n - i,
        {
            let v: i64 = a[i];
            nxt = if v > cur && v < nxt {
                v
            } else {
                nxt
            };
            i = i + 1;
        }
        nxt
    }

    spec fn within(a: &[i64], n: usize) -> bool {
        n <= a.len()
    }
}

#[summary("Longest strictly increasing subsequence length")]
mod tasks {
    spec fn dp_ok(d: &[usize], i: usize) -> bool {
        i <= d.len() && (forall|k: usize| k < i ==> 1 <= #[trigger] d[k] && d[k] <= k + 1)
    }

    #[effects(pure)]
    #[uses(dp_ok, lis_ok, small)]
    fn lis_length(arr: &[i64]) -> (r: usize)
        requires small(arr),
        ensures lis_ok(arr, r),
    {
        let n: usize = arr.len();
        let mut dp: [usize; 100] = [1; 100];
        let mut best: usize = 0;
        let mut i: usize = 0;
        while i < n
            invariant dp_ok(&dp, i), best <= i, i > 0 ==> best >= 1, i <= n, n == arr.len(), n <= 100,
            decreases n - i,
        {
            let mut cur: usize = 1;
            let mut j: usize = 0;
            while j < i
                invariant dp_ok(&dp, i), j <= i, i < n, n <= 100, 1 <= cur, cur <= j + 1,
                decreases i - j,
            {
                if arr[j] < arr[i] {
                    if dp[j] + 1 > cur {
                        cur = dp[j] + 1;
                    }
                }
                j = j + 1;
            }
            dp[i] = cur;
            if cur > best {
                best = cur;
            }
            i = i + 1;
        }
        best
    }

    spec fn lis_ok(a: &[i64], r: usize) -> bool {
        r <= a.len() && (a.len() > 0 ==> r >= 1)
    }

    spec fn small(a: &[i64]) -> bool {
        a.len() <= 100
    }
}

#[summary("next_permutation with exact characterization of the result")]
mod tasks {
    spec fn jscan_inv(o: &[i64], a: &[i64], i: usize, j: usize) -> bool {
        a.len() == o.len() && 1 <= i && i <= j && j < a.len() && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == o[p]) && a[i] > a[i - 1] && (forall|p: usize| i <= p && p + 1 < a.len() ==> #[trigger] a[p] >= a[p + 1]) && (forall|p: usize| j < p && p < a.len() ==> #[trigger] a[p] <= a[i - 1])
    }

    spec fn lo_ok(a: &[i64], lo: usize) -> bool {
        lo <= a.len()
    }

    #[effects(pure)]
    #[uses(jscan_inv, lo_ok, next_shape, non_inc, np_post, rev_post, scan_inv)]
    fn next_permutation(a: &mut [i64]) -> (r: bool)
        ensures np_post(old(a), a, r),
    {
        let n: usize = a.len();
        if n < 2 {
            false
        } else {
            let mut i: usize = n - 1;
            while i > 0 && a[i - 1] >= a[i]
                invariant scan_inv(old(a), a, i),
                decreases i,
            {
                i = i - 1;
            }
            if i == 0 {
                reverse_from(a, 0);
                false
            } else {
                let mut j: usize = n - 1;
                while a[j] <= a[i - 1]
                    invariant jscan_inv(old(a), a, i, j),
                    decreases j,
                {
                    j = j - 1;
                }
                let t: i64 = a[i - 1];
                let u: i64 = a[j];
                a[i - 1] = u;
                a[j] = t;
                reverse_from(a, i);
                true
            }
        }
    }

    spec fn next_shape(o: &[i64], a: &[i64], k: usize, j: usize) -> bool {
        a.len() == o.len() && k < j && j < o.len() && (forall|p: usize| p < k ==> #[trigger] a[p] == o[p]) && o[k] < o[k + 1] && (forall|p: usize| k + 1 <= p && p + 1 < o.len() ==> #[trigger] o[p] >= o[p + 1]) && o[j] > o[k] && (forall|p: usize| j < p && p < o.len() ==> #[trigger] o[p] <= o[k]) && a[k] == o[j] && (forall|p: usize| k + 1 <= p && p < o.len() ==> o.len() + k - p == j && #[trigger] a[p] == o[k] || o.len() + k - p != j && a[p] == o[o.len() + k - p])
    }

    spec fn non_inc(a: &[i64]) -> bool {
        forall|p: usize| p + 1 < a.len() ==> #[trigger] a[p] >= a[p + 1]
    }

    spec fn np_post(o: &[i64], a: &[i64], r: bool) -> bool {
        a.len() == o.len() && (r ==> (exists|k: usize, j: usize| #[trigger] next_shape(o, a, k, j))) && (!r ==> non_inc(o) && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == o[a.len() - 1 - p]))
    }

    spec fn rev_inv(o: &[i64], a: &[i64], lo: usize, l: usize, h: usize) -> bool {
        a.len() == o.len() && lo <= l && l <= h && h <= a.len() && l + h == a.len() + lo && (forall|p: usize| p < lo ==> #[trigger] a[p] == o[p]) && (forall|p: usize| lo <= p && p < l ==> #[trigger] a[p] == o[a.len() + lo - 1 - p]) && (forall|p: usize| l <= p && p < h ==> #[trigger] a[p] == o[p]) && (forall|p: usize| h <= p && p < a.len() ==> #[trigger] a[p] == o[a.len() + lo - 1 - p])
    }

    spec fn rev_post(o: &[i64], a: &[i64], lo: usize) -> bool {
        a.len() == o.len() && lo <= a.len() && (forall|p: usize| p < lo ==> #[trigger] a[p] == o[p]) && (forall|p: usize| lo <= p && p < a.len() ==> #[trigger] a[p] == o[a.len() + lo - 1 - p])
    }

    #[effects(pure)]
    #[uses(lo_ok, rev_inv, rev_post)]
    fn reverse_from(a: &mut [i64], lo: usize) -> ()
        requires lo_ok(a, lo),
        ensures rev_post(old(a), a, lo),
    {
        let n: usize = a.len();
        let mut l: usize = lo;
        let mut h: usize = n;
        while l + 1 < h
            invariant rev_inv(old(a), a, lo, l, h),
            decreases h - l,
        {
            let t: i64 = a[l];
            let u: i64 = a[h - 1];
            a[l] = u;
            a[h - 1] = t;
            l = l + 1;
            h = h - 1;
        }
    }

    spec fn scan_inv(o: &[i64], a: &[i64], i: usize) -> bool {
        a.len() == o.len() && i < a.len() && (forall|p: usize| p < a.len() ==> #[trigger] a[p] == o[p]) && (forall|p: usize| i <= p && p + 1 < a.len() ==> #[trigger] a[p] >= a[p + 1])
    }
}

#[summary("coin change counting via DP")]
mod tasks {
    #[effects(pure)]
    #[uses(valid)]
    fn count_change(coins: &[i64], total: i64) -> (r: u64)
        requires valid(coins, total),
    {
        let t: usize = total as usize;
        let mut dp: [u64; 501] = [0; 501];
        dp[0] = 1;
        let mut i: usize = 0;
        while i < coins.len()
            invariant i <= coins.len(), t <= 500, valid(coins, total),
            decreases coins.len() - i,
        {
            let c: usize = coins[i] as usize;
            let mut j: usize = c;
            while j <= t
                invariant c >= 1, c <= 500, j >= c, t <= 500, j <= 501,
                decreases t + 1 - j,
            {
                dp[j] = dp[j].wrapping_add(dp[j - c]);
                j = j + 1;
            }
            i = i + 1;
        }
        dp[t]
    }

    spec fn valid(coins: &[i64], total: i64) -> bool {
        coins.len() <= 12 && 0 <= total && total <= 500 && (forall|i: usize| i < coins.len() ==> 1 <= #[trigger] coins[i] && coins[i] <= 500)
    }
}

#[summary("0/1 knapsack by DP")]
mod tasks {
    spec fn best(w: &[i64], v: &[i64], n: usize, c: i64) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if w[n - 1] <= c {
            if best(w, v, n - 1, c) >= v[n - 1] + best(w, v, n - 1, c - w[n - 1]) {
                best(w, v, n - 1, c)
            } else {
                v[n - 1] + best(w, v, n - 1, c - w[n - 1])
            }
        } else {
            best(w, v, n - 1, c)
        }
    }

    spec fn dom(capacity: usize, w: &[i64], v: &[i64]) -> bool {
        capacity <= 1000 && w.len() == v.len() && w.len() <= 30 && (forall|i: usize| i < w.len() ==> 1 <= #[trigger] w[i] && w[i] <= 1000) && (forall|i: usize| i < v.len() ==> 0 <= #[trigger] v[i] && v[i] <= 1000000000000000)
    }

    #[effects(pure)]
    #[uses(best, dom, tab)]
    fn knapsack(capacity: usize, weights: &[i64], values: &[i64]) -> (r: i64)
        requires dom(capacity, weights, values),
        ensures r == best(weights, values, weights.len(), capacity),
    {
        let n: usize = weights.len();
        let mut dp: [i64; 1001] = [0; 1001];
        let mut nw: [i64; 1001] = [0; 1001];
        let mut i: usize = 0;
        while i < n
            invariant i <= n, n == weights.len(), n <= 30, dom(capacity, weights, values), capacity <= 1000, tab(&dp, weights, values, i, capacity, capacity + 1),
            decreases n - i,
        {
            let mut c: usize = 0;
            while c <= capacity
                invariant c <= capacity + 1, i < n, n == weights.len(), n <= 30, dom(capacity, weights, values), capacity <= 1000, tab(&dp, weights, values, i, capacity, capacity + 1), tab(&nw, weights, values, i + 1, capacity, c),
                decreases capacity + 1 - c,
            {
                let x: i64 = step(&dp, weights, values, i, capacity, c);
                nw[c] = x;
                c = c + 1;
            }
            let mut j: usize = 0;
            while j <= capacity
                invariant j <= capacity + 1, i < n, capacity <= 1000, tab(&nw, weights, values, i + 1, capacity, capacity + 1), tab(&dp, weights, values, i + 1, capacity, j),
                decreases capacity + 1 - j,
            {
                dp[j] = nw[j];
                j = j + 1;
            }
            i = i + 1;
        }
        dp[capacity]
    }

    #[effects(pure)]
    #[uses(best, dom, tab)]
    fn step(dp: &[i64], w: &[i64], v: &[i64], i: usize, cap: usize, c: usize) -> (res: i64)
        requires dom(cap, w, v), i < w.len(), c <= cap, dp.len() == 1001, tab(dp, w, v, i, cap, cap + 1),
        ensures res == best(w, v, i + 1, c), 0 <= res, res <= 1000000000000000 * (i + 1),
    {
        let wi: i64 = w[i];
        let vi: i64 = v[i];
        let mut x: i64 = dp[c];
        if wi <= c as i64 {
            let y: i64 = dp[c - wi as usize] + vi;
            if y > x {
                x = y;
            }
        }
        x
    }

    spec fn tab(d: &[i64], w: &[i64], v: &[i64], k: usize, cap: usize, lim: usize) -> bool {
        forall|c: usize| c < lim && c <= cap && c < d.len() ==> #[trigger] d[c] == best(w, v, k, c) && 0 <= d[c] && d[c] <= 1000000000000000 * k
    }
}

#[summary("Levenshtein edit distance")]
mod tasks {
    #[effects(pure)]
    #[uses(row_ok)]
    fn copy_row(a: &[i64], b: &[i64], i: usize, prev: &mut [usize], cur: &[usize], n: usize) -> ()
        requires prev.len() == 65, n <= 65, row_ok(a, b, i, cur, n),
        ensures row_ok(a, b, i, prev, n),
    {
        let mut k: usize = 0;
        while k < n
            invariant k <= n, n <= 65, prev.len() == 65, row_ok(a, b, i, cur, n), row_ok(a, b, i, prev, k),
            decreases n - k,
        {
            prev[k] = cur[k];
            k = k + 1;
        }
    }

    spec fn cost(a: &[i64], b: &[i64], i: usize, j: usize) -> usize {
        if a[i - 1] == b[j - 1] {
            0
        } else {
            1
        }
    }

    spec fn ed(a: &[i64], b: &[i64], i: usize, j: usize) -> usize
        decreases i + j,
    {
        if i == 0 {
            j
        } else if j == 0 {
            i
        } else {
            min3(ed(a, b, i - 1, j) + 1, ed(a, b, i, j - 1) + 1, ed(a, b, i - 1, j - 1) + cost(a, b, i, j))
        }
    }

    #[effects(pure)]
    #[uses(ed, is_ed, row_ok, small)]
    fn edit_distance(a: &[i64], b: &[i64]) -> (r: usize)
        requires small(a, b),
        ensures is_ed(a, b, r),
    {
        let n: usize = a.len();
        let m: usize = b.len();
        let mut prev: [usize; 65] = [0; 65];
        let mut cur: [usize; 65] = [0; 65];
        let mut j: usize = 0;
        while j <= m
            invariant j <= m + 1, m == b.len(), m <= 64, row_ok(a, b, 0, &prev, j),
            decreases m + 1 - j,
        {
            prev[j] = j;
            j = j + 1;
        }
        let mut i: usize = 0;
        while i < n
            invariant i <= n, n == a.len(), m == b.len(), m <= 64, n <= 64, row_ok(a, b, i, &prev, m + 1), cur.len() == 65,
            decreases n - i,
        {
            next_row(a, b, i, &prev, &mut cur);
            copy_row(a, b, i + 1, &mut prev, &cur, m + 1);
            i = i + 1;
        }
        prev[m]
    }

    spec fn is_ed(a: &[i64], b: &[i64], r: usize) -> bool {
        r == ed(a, b, a.len(), b.len())
    }

    spec fn min3(x: usize, y: usize, z: usize) -> usize {
        if x <= y && x <= z {
            x
        } else if y <= z {
            y
        } else {
            z
        }
    }

    #[effects(pure)]
    #[uses(cost, ed, min3, row_ok, small)]
    fn next_row(a: &[i64], b: &[i64], i: usize, prev: &[usize], cur: &mut [usize]) -> ()
        requires small(a, b), i < a.len(), row_ok(a, b, i, prev, b.len() + 1), cur.len() == 65,
        ensures row_ok(a, b, i + 1, cur, b.len() + 1),
    {
        let m: usize = b.len();
        cur[0] = i + 1;
        let mut j2: usize = 1;
        while j2 <= m
