#[summary("count primes <= n by trial division")]
mod tasks {
    #[effects(pure)]
    #[uses(count_res, count_upto, iloop, is_prime, pre_ok, small)]
    fn count_primes(n: u64) -> (r: u64)
        requires small(n),
        ensures count_res(r, n),
    {
        let mut i: u64 = 0;
        let mut c: u64 = 0;
        while i < n
            invariant iloop(i, n, c),
            decreases n - i,
        {
            i = i + 1;
            if i >= 2 {
                if is_prime_exec(i) {
                    c = c + 1;
                }
            }
        }
        c
    }

    spec fn count_res(r: u64, n: u64) -> bool {
        r == count_upto(n)
    }

    spec fn count_upto(n: u64) -> u64
        decreases n,
    {
        if n == 0 {
            0
        } else {
            count_upto(n - 1) + (if is_prime(n) { 1 } else { 0 })
        }
    }

    spec fn dloop(p: u64, d: u64) -> bool {
        2 <= d && d <= p && no_div_below(p, d)
    }

    spec fn fnd(p: u64, d: u64, found: bool) -> bool {
        found ==> d < p && p % d == 0
    }

    spec fn iloop(i: u64, n: u64, r: u64) -> bool {
        i <= n && r <= i && r == count_upto(i)
    }

    spec fn is_prime(p: u64) -> bool {
        p >= 2 && (forall|d: u64| 2 <= d && d < p ==> #[trigger] (p % d) != 0)
    }

    #[effects(pure)]
    #[uses(dloop, fnd, is_prime, no_div_below, pre_ok, prime_res)]
    fn is_prime_exec(p: u64) -> (b: bool)
        requires pre_ok(p),
        ensures prime_res(b, p),
    {
        let mut d: u64 = 2;
        let mut found: bool = false;
        while d < p && !found
            invariant dloop(p, d), fnd(p, d, found),
            decreases if found { 0 } else { p - d },
        {
            if p % d == 0 {
                found = true;
            } else {
                d = d + 1;
            }
        }
        !found
    }

    spec fn no_div_below(p: u64, d: u64) -> bool {
        forall|k: u64| 2 <= k && k < d ==> #[trigger] (p % k) != 0
    }

    spec fn pre_ok(p: u64) -> bool {
        p >= 2
    }

    spec fn prime_res(b: bool, p: u64) -> bool {
        b == is_prime(p)
    }

    spec fn small(n: u64) -> bool {
        n <= 20000
    }
}

