#[summary("binomial coefficient via Pascal row DP")]
mod tasks {
    #[effects(pure)]
    #[uses(pas, result_ok, row_init, row_ok)]
    fn binomial(n: u64, k: u64) -> (r: u64)
        requires n <= 67,
        ensures result_ok(n, k, r),
    {
        let mut row: [u64; 68] = [0; 68];
        row[0] = 1;
        let mut i: u64 = 0;
        while i < n
            invariant i <= n, n <= 67, row_init(&row, i),
            decreases n - i,
        {
            let mut j: usize = 67;
            while j >= 1
                invariant j <= 67, i < n, n <= 67, row_ok(&row, i, j),
                decreases j,
            {
                row[j] = row[j].wrapping_add(row[j - 1]);
